import{_ as o,o as t,c as i,a3 as s}from"./chunks/framework.DhF4LrUq.js";const u=JSON.parse('{"title":"Identity and SSO","description":"Identity and SSO - OIDC and SAML login flows, provisioning postures, and SCIM joiner-mover-leaver cascades.","frontmatter":{"description":"Identity and SSO - OIDC and SAML login flows, provisioning postures, and SCIM joiner-mover-leaver cascades."},"headers":[],"relativePath":"concepts/identity-sso.md","filePath":"concepts/identity-sso.md"}'),n={name:"concepts/identity-sso.md"};function a(r,e,d,l,h,c){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="identity-and-sso" tabindex="-1">Identity and SSO <a class="header-anchor" href="#identity-and-sso" aria-label="Permalink to &quot;Identity and SSO&quot;">​</a></h1><p>ShipperDog fits your corporate identity stack rather than replacing it. Console users can sign in with email and password, or the whole organization can be routed through your identity provider — OIDC and SAML 2.0 both supported — with SCIM 2.0 provisioning automating joiners and leavers. Testers use invitation links and passwords; the portal is their only surface.</p><h2 id="local-accounts" tabindex="-1">Local accounts <a class="header-anchor" href="#local-accounts" aria-label="Permalink to &quot;Local accounts&quot;">​</a></h2><p>Email and password, invitation-only registration, Argon2id password hashing, lockout after repeated failures, single-use password resets. Sessions are short-lived access tokens with rotating refresh tokens; suspension, deactivation, and role demotions revoke sessions immediately. Personal access tokens (for the CLI and CI) are shown once and stored only as digests.</p><h2 id="single-sign-on" tabindex="-1">Single sign-on <a class="header-anchor" href="#single-sign-on" aria-label="Permalink to &quot;Single sign-on&quot;">​</a></h2><p>An Organization Admin configures the organization&#39;s provider — OIDC (Google Workspace, Microsoft Entra, Okta) or SAML 2.0 — and console users sign in through it. The flows are backend-driven:</p><ul><li><strong>OIDC</strong> uses the authorization-code flow with PKCE. The console&#39;s login page probes the organization&#39;s SSO options and hands the browser to the provider; the verified callback returns the browser to the console with a one-time session code that is exchanged for exactly the session a local login mints — SSO sessions are local sessions, with the same rotation and revocation.</li><li><strong>SAML 2.0</strong> supports both SP-initiated and IdP-initiated flows. The platform&#39;s per-organization SP metadata document gives you the entityID and assertion-consumer URL to register with the IdP. Assertions are verified against certificates pinned from the IdP metadata you upload, with signature wrapping, algorithm pinning, and replay defenses applied before anything in the payload is acted on.</li></ul><p>Both kinds share one identity-resolution layer:</p><ul><li><strong>Linking</strong> — once a provider subject is linked to an account, logins resolve through the subject, never by re-deriving from email.</li><li><strong>Provisioning</strong> — <code>INVITED_ONLY</code> links existing members only; <code>JIT</code> additionally provisions password-less accounts on first login with a configured default role (least-privilege floor: <code>VIEWER</code>).</li><li><strong>Role mapping</strong> — group claims or attributes map provider groups to organization roles, applied on every login; the most privileged mapped group wins.</li><li><strong>Session end</strong> — OIDC back-channel logout revokes the linked account&#39;s sessions when the IdP says so. An optional SSO mandate refuses password login for members entirely, while platform administrators always keep local break-glass login.</li><li><strong>Offboarding follows the provider</strong> — when the provider asserts the configured inactive claim, the account hard-locks and sessions revoke.</li></ul><h2 id="scim-provisioning" tabindex="-1">SCIM provisioning <a class="header-anchor" href="#scim-provisioning" aria-label="Permalink to &quot;SCIM provisioning&quot;">​</a></h2><p>The SCIM 2.0 connector carries the joiner/leaver automation: your IdP pushes Users and Groups to ShipperDog, authenticated by a per-organization connector bearer token (shown once, rotatable, revocable — the provisioning freeze is just turning it off).</p><ul><li><strong>Users</strong> provision through an externalId-keyed upsert; accounts and organization roles derive from the pushed state.</li><li><strong>Groups</strong> map to organization roles through mapping rules you author (for example, an &quot;app-owners&quot; group maps to <code>APP_OWNER</code>).</li><li><strong>The leaver cascade</strong> is the security-critical leg: deactivating a user in the IdP suspends every membership and tenant-tester membership the account holds, in one act — access ends at the next request, and a deliberate doctrine means a re-provision does not silently reactivate what the cascade suspended; restoration is a human decision.</li></ul><h2 id="testers-are-different-on-purpose" tabindex="-1">Testers are different on purpose <a class="header-anchor" href="#testers-are-different-on-purpose" aria-label="Permalink to &quot;Testers are different on purpose&quot;">​</a></h2><p>Testers onboard through invitations (see the <a href="/shipperdog/snapshot/get-started/five-minute-install">five-minute install</a>), not through your IdP. Their access is tenant membership plus explicit version grants — see <a href="/shipperdog/snapshot/concepts/authorization">authorization</a> — and their login, refresh, and token use are refused the moment their tester record is suspended or deactivated.</p><h2 id="where-to-go-deeper" tabindex="-1">Where to go deeper <a class="header-anchor" href="#where-to-go-deeper" aria-label="Permalink to &quot;Where to go deeper&quot;">​</a></h2><ul><li><a href="/shipperdog/snapshot/concepts/security-model">Security model</a> — credential storage, session posture, auditing</li><li>Developer detail: the <a href="https://github.com/ShristiLabs/shipperdog/blob/main/docs/authentication.md" target="_blank" rel="noreferrer">authentication</a> module doc (endpoints, token semantics, the OIDC/SAML flows and their configuration) and the <a href="https://github.com/ShristiLabs/shipperdog/blob/main/docs/scim.md" target="_blank" rel="noreferrer">SCIM</a> provisioning guide (routes, mapping rules, the leaver cascade, IdP setup).</li></ul>',16)])])}const g=o(n,[["render",a]]);export{u as __pageData,g as default};
